    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": [],
    "motivo": "Término da linha base declarado como D12.",
    "unidade": "dia_corrido"
  },
  "fim_novo": {
    "estado": "exato",
    "valor": 10,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_a781", "localizador": "L01"},
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_7d2f", "localizador": "L01"},
      {"fonte_id": "f_d7254f", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "Preparar e usinar terminam em D2 e D4; integrar termina em D7. Ensaiar termina em D9. O dossiê, com duração reduzida para 1 dia e início não antes de D8, termina em D9. Inspecionar termina em D10, quando libera a estação.",
    "unidade": "dia_corrido"
  },
  "delta_dias": {
    "estado": "exato",
    "valor": -2,
    "direcao": "reducao",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_a781", "localizador": "L01"},
      {"fonte_id": "f_7d2f", "localizador": "L01"},
      {"fonte_id": "f_d7254f", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "D10 menos o término base D12 resulta em antecipação de 2 dias corridos.",
    "unidade": "dia_corrido"
  },
  "custo_base": {
    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"}
    ],
    "lacunas": [],
    "motivo": "Custo total da linha base declarado como R$ 1.650,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 150000,
    "direcao": "desconhecida",
    "evidencias": [
      {"fonte_id": "f_b915", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_d7254f", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "As seis parcelas fixas somam R$ 1.000,00. O término em D10 usa exatamente os 10 dias de cobertura; com o crédito expresso da extensão não usada, o apoio custa apenas o fixo de R$ 500,00. Total: R$ 1.500,00.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": -15000,
    "direcao": "reducao",
    "evidencias": [
      {"fonte_id": "f_36c2", "localizador": "L02"},
      {"fonte_id": "f_b915", "localizador": "L01"},
      {"fonte_id": "f_493d", "localizador": "L01"},
      {"fonte_id": "f_d7254f", "localizador": "L01"}
    ],
    "lacunas": [],
    "motivo": "R$ 1.500,00 no novo custo menos R$ 1.650,00 na linha base resulta em economia de R$ 150,00.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso encurta o dossiê para 1 dia, mas sua restrição de início em D8 permanece; o término final passa de D12 para D10. O aditivo autoriza creditar toda a extensão de apoio não usada: em D10, o apoio fica no valor fixo de R$ 500,00, reduzindo o custo total em R$ 150,00."
}

